function makeSession(n, title) {
  return { id: `sess_${Date.now()}_${n}`, number: n, title: title || `Session ${n}`, date: "", attendees: 0, status: "planned", recordingLink: "", notes: "", attendance: [] };
}
function makeLaneSessions(laneKey) {
  const titles = LANE_SESSIONS[laneKey] || [];
  return Array.from({length:12}, (_,i) => makeSession(i+1, titles[i]));
}

