                  const stageInfo = { potential:{color:C.teal,icon:"🔍"}, shortlisted:{color:C.gold,icon:"📋"}, auditioned:{color:C.purple,icon:"🎤"}, confirmed:{color:C.green,icon:"✅"}, rejected:{color:C.red,icon:"✗"} }[status];
