function getDayIndex(arr) {
  const day = new Date().getDate() + new Date().getMonth() * 31;
  return day % arr.length;
}

function getRandomFact() {
  const key = "artium-facts-seen";
  let seenIndices = [];
  try { seenIndices = JSON.parse(localStorage.getItem(key) || "[]"); } catch {}
  const allIndices = QUIRKY_FACTS.map((_, i) => i);
  const unseenIndices = allIndices.filter(i => !seenIndices.includes(i));
  const pool = unseenIndices.length > 0 ? unseenIndices : allIndices;
  const picked = pool[Math.floor(Math.random() * pool.length)];
  const newSeen = unseenIndices.length > 0 ? [...seenIndices, picked] : [picked];
  try { localStorage.setItem(key, JSON.stringify(newSeen)); } catch {}
  return QUIRKY_FACTS[picked];
}

function computeFocus(data) {
  const items = [];
  // ATDP: pending contracts
  const noCt = (data.atdp?.students||[]).filter(s=>s.status==="active"&&!s.contract);
  if(noCt.length) items.push({ icon:"📄", color:"#f0c060", label:`${noCt.length} student${noCt.length>1?"s":""} missing contract`, sub: noCt.slice(0,2).map(s=>s.name).join(", ")+(noCt.length>2?` +${noCt.length-2} more`:""), section:"atdp" });
  // Grooming lanes stalling
  const lanes = data.atdp?.groomingLanes||[];
  const stalledLanes = lanes.filter(l=>{
    const done = l.sessions.filter(s=>s.status==="done").length;
    return done < 3; // less than 3 sessions done is stalling
  });
  if(stalledLanes.length) items.push({ icon:"🌱", color:"#7dd3f5", label:`${stalledLanes.length} grooming lane${stalledLanes.length>1?"s":""} need attention`, sub: stalledLanes.map(l=>l.name).join(", "), section:"atdp" });
  // Devotional: in progress
  const devProd = (data.originals?.devotional||[]).filter(d=>d.prodStatus==="in progress");
  if(devProd.length) items.push({ icon:"🎵", color:"#c4b5fd", label:`${devProd.length} devotional track${devProd.length>1?"s":""} in production`, sub:"Need follow-up to move forward", section:"originals" });
  // Devotional: scratch not received
  const devNoScratch = (data.originals?.devotional||[]).filter(d=>d.scratchStatus==="not yet");
  if(devNoScratch.length) items.push({ icon:"🎤", color:"#f75fa0", label:`${devNoScratch.length} teacher${devNoScratch.length>1?"s":""} haven't sent scratch yet`, sub:devNoScratch.slice(0,2).map(d=>d.name).join(", ")+(devNoScratch.length>2?` +${devNoScratch.length-2} more`:""), section:"originals" });
  // Workshops delayed
  const delayed = (data.atdp?.workshops||[]).filter(w=>w.status==="delayed");
  if(delayed.length) items.push({ icon:"⚠️", color:"#fb7185", label:`${delayed.length} workshop${delayed.length>1?"s":""} delayed`, sub:delayed.map(w=>w.name).join(", "), section:"atdp" });
  // unMute content pending
  const allPerf = (data.unmute?.editions||[]).flatMap(e=>e.performers||[]);
  const pendingYt = allPerf.filter(p=>p.ytStatus==="pending"||p.ytStatus==="planned");
  if(pendingYt.length) items.push({ icon:"📹", color:"#6ee7b7", label:`${pendingYt.length} unMute video${pendingYt.length>1?"s":""} not yet released`, sub:"Content pipeline needs a push", section:"unmute" });
  return items.slice(0,3);
}

function computeWeekWins(data) {
  const wins = [];
  const relStudents = (data.atdp?.students||[]).filter(s=>s.status==="active");
  wins.push(`${relStudents.length} active ATDP students across BLR, MUM & CHN`);
  const doneSessions = (data.atdp?.groomingLanes||[]).flatMap(l=>l.sessions).filter(s=>s.status==="done");
  if(doneSessions.length) wins.push(`${doneSessions.length} grooming sessions completed across all lanes`);
  const relOriginals = (data.originals?.flagship||[]).filter(f=>f.status==="released");
  if(relOriginals.length) wins.push(`${relOriginals.map(f=>'"'+f.title+'"').join(", ")} released on all platforms`);
  const relYt = (data.unmute?.editions||[]).flatMap(e=>e.performers||[]).filter(p=>p.ytStatus==="released");
  if(relYt.length) wins.push(`${relYt.length} unMute performances live on YouTube`);
  const scratchReceived = (data.originals?.devotional||[]).filter(d=>d.scratchStatus==="received");
  if(scratchReceived.length) wins.push(`${scratchReceived.length} devotional scratches received from teachers`);
  const doneWs = (data.atdp?.workshops||[]).filter(w=>w.status==="done");
  if(doneWs.length) wins.push(`Workshop "${doneWs[doneWs.length-1].name}" delivered successfully`);
  return wins.slice(0,5);
}

